one-out-single:
MATCH (a:`Hub`) USING INDEX SEEK a:`Hub`(`hubId`) WHERE a.`hubId` IN [$stableId, $stableInteger] WITH a ORDER BY elementId(a) LIMIT 1
CALL { WITH a CALL { WITH a MATCH (a)-[r:`A`]->(n:`Hub`) WHERE n <> a RETURN n, r, true AS isTarget } WITH DISTINCT n LIMIT $countCap + 1 RETURN count(n) AS matches }
RETURN matches, false AS frontierBounded, false AS supernodeSkipped

