CALL { WITH a CALL { WITH a MATCH (a)-[r:`B`]->(n:`Hub`) WHERE n <> a RETURN n, r, true AS isTarget UNION ALL WITH a MATCH (a)-[r:`C`]->(n:`Leaf`) WHERE n <> a RETURN n, r, false AS isTarget } WITH n, isTarget LIMIT $countCap + 1 WITH collect({n: n, isTarget: isTarget}) AS found RETURN size(found) > $countCap AS frontierBounded, found[..$countCap] AS nbs }
